class Solution:
    def countUnivalSubtrees(self, root):
        count = 0

        def helper(node):
            nonlocal count
            if not node:
                return True
            left = helper(node.left)
            right = helper(node.right)
            if left and right:
                if node.left and node.left.val != node.val:
                    return False
                if node.right and node.right.val != node.val:
                    return False
                count += 1
                return True
            return False

        helper(root)
        return count

