class Solution:
    def minCost(self, costs: List[List[int]]) -> int:
        if not costs:
            return 0

        prev = costs[0]
        for i in range(1, len(costs)):
            curr = costs[i]
            p0, p1, p2 = prev
            curr[0] += p1 if p1 < p2 else p2
            curr[1] += p0 if p0 < p2 else p2
            curr[2] += p0 if p0 < p1 else p1
            prev = curr

        return prev[0] if prev[0] < prev[1] else (prev[1] if prev[1] < prev[2] else prev[2])

