class Solution:
    def singleNumber(self, nums: List[int]) -> List[int]:
        # Single pass: compute XOR sum while tracking partition
        xor_sum = 0
        a = 0
        b = 0

        # First pass to get xor_sum
        for num in nums:
            xor_sum ^= num

        # Get rightmost set bit
        diff_bit = xor_sum & -xor_sum

        # Second pass to partition
        for num in nums:
            if num & diff_bit:
                a ^= num
            else:
                b ^= num

        return [a, b]

class Solution:
    def nthUglyNumber(self, n: int) -> int:
        ugly = [1] * n
        i2 = i3 = i5 = 0
        for idx in range(1, n):
            next2 = ugly[i2] * 2
            next3 = ugly[i3] * 3
            next5 = ugly[i5] * 5
            next_ugly = next2 if next2 <= next3 else next3
            if next5 < next_ugly:
                next_ugly = next5
            ugly[idx] = next_ugly
            if next_ugly == next2:
                i2 += 1
            if next_ugly == next3:
                i3 += 1
            if next_ugly == next5:
                i5 += 1
        return ugly[-1]

class Solution:
    def minCostII(self, costs):
        if not costs:
            return 0
        n, k = len(costs), len(costs[0])

        prev_row = costs[0]

        for house in range(1, n):
            curr_row = [0] * k
            # Find the first and second minimum in the previous row
            min1 = float('inf')
            min2 = float('inf')
            min1_color = -1
            for color in range(k):
                val = prev_row[color]
                if val < min1:
                    min2 = min1
                    min1 = val
                    min1_color = color
                elif val < min2:
                    min2 = val

            cost_house = costs[house]
            for color in range(k):
                if color != min1_color:
                    curr_row[color] = cost_house[color] + min1
                else:
                    curr_row[color] = cost_house[color] + min2
            prev_row = curr_row

        return min(prev_row)

