class Solution:
    def generatePalindromes(self, s: str) -> list[str]:
        # Count character frequencies using a simple dict
        freq = {}
        for char in s:
            freq[char] = freq.get(char, 0) + 1

        # Check palindrome possibility and find odd character
        odd_char = ''
        odd_count = 0
        half_chars = []

        for char, count in freq.items():
            if count % 2 != 0:
                odd_char = char
                odd_count += 1
            half_chars.extend([char] * (count // 2))

        if odd_count > 1:
            return []

        # Generate unique permutations and build palindromes directly
        result = []
        seen_perms = set()

        for perm in permutations(half_chars):
            if perm not in seen_perms:
                seen_perms.add(perm)
                half_str = ''.join(perm)
                result.append(half_str + odd_char + half_str[::-1])

        return result

