class Solution:
    def closestValue(self, root: TreeNode, target: float) -> int:
        closest = root.val
        diff = abs(root.val - target)
        while root:
            cur_diff = abs(root.val - target)
            if cur_diff < diff:
                closest = root.val
                diff = cur_diff
            elif cur_diff == diff and root.val < closest:
                closest = root.val
            root = root.left if target < root.val else root.right
        return closest

