class Solution:
    def inorderSuccessor(self, root: TreeNode, p: TreeNode) -> TreeNode:
        # If p has a right subtree, successor is the leftmost node in that subtree
        if p.right:
            current = p.right
            while current.left:
                current = current.left
            return current

        # Otherwise, find the deepest ancestor for which p is in its left subtree
        successor = None
        current = root
        while current:
            if current.val > p.val:
                successor = current
                current = current.left
            else:
                current = current.right
        return successor

