class Solution:
    def removeInvalidParentheses(self, s: str) -> List[str]:
        # Calculate the number of misplaced left and right parentheses
        left_remove = 0
        right_remove = 0
        for char in s:
            if char == '(':
                left_remove += 1
            elif char == ')':
                if left_remove == 0:
                    right_remove += 1
                else:
                    left_remove -= 1

        # Use a set to avoid duplicates
        result = set()

        def backtrack(index, left_count, right_count, left_rem, right_rem, current):
            if index == len(s):
                if left_rem == 0 and right_rem == 0:
                    result.add(current)
                return
            char = s[index]
            # Option 1: discard the current character if it's a parenthesis and we have removals left
            if char == '(' and left_rem > 0:
                backtrack(index + 1, left_count, right_count, left_rem - 1, right_rem, current)
            elif char == ')' and right_rem > 0:
                backtrack(index + 1, left_count, right_count, left_rem, right_rem - 1, current)

            # Option 2: keep the current character
            if char != '(' and char != ')':
                backtrack(index + 1, left_count, right_count, left_rem, right_rem, current + char)
            elif char == '(':
                backtrack(index + 1, left_count + 1, right_count, left_rem, right_rem, current + char)
            elif char == ')' and left_count > right_count:
                backtrack(index + 1, left_count, right_count + 1, left_rem, right_rem, current + char)

        backtrack(0, 0, 0, left_remove, right_remove, "")
        return list(result)

class Solution:
    def maxCoins(self, nums: list[int]) -> int:
        padded = [1] + nums + [1]
        n = len(padded)
        # Use flat array instead of 2D list to reduce memory overhead
        # and improve cache locality
        dp = [0] * (n * n)

        for length in range(2, n):
            for left in range(n - length):
                right = left + length
                base = left * n
                boundary_product = padded[left] * padded[right]
                best = 0
                left_base = base
                for k in range(left + 1, right):
                    coins = boundary_product * padded[k] + dp[left_base + k] + dp[k * n + right]
                    if coins > best:
                        best = coins
                dp[left_base + right] = best

        return dp[n - 1]

