class Solution:
    def verticalOrder(self, root: TreeNode) -> list[list[int]]:
        if not root:
            return []

        min_col = 0
        max_col = 0
        column_table = {}
        queue = deque([(root, 0)])

        while queue:
            node, column = queue.popleft()
            if column in column_table:
                column_table[column].append(node.val)
            else:
                column_table[column] = [node.val]

            if node.left:
                queue.append((node.left, column - 1))
                if column - 1 < min_col:
                    min_col = column - 1
            if node.right:
                queue.append((node.right, column + 1))
                if column + 1 > max_col:
                    max_col = column + 1

        return [column_table[col] for col in range(min_col, max_col + 1)]
